import{_ as a,o as e,c as o,ag as i}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"快捷指令","description":"","frontmatter":{},"headers":[],"relativePath":"efficiency/shortcuts.md","filePath":"efficiency/shortcuts.md","lastUpdated":null}'),r={name:"efficiency/shortcuts.md"};function l(d,t,s,h,n,c){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="快捷指令" tabindex="-1">快捷指令 <a class="header-anchor" href="#快捷指令" aria-label="Permalink to &quot;快捷指令&quot;">​</a></h1><blockquote><p>效率翻倍（iOS专属）</p></blockquote><h2 id="一、实体操作按钮" tabindex="-1">一、实体操作按钮 <a class="header-anchor" href="#一、实体操作按钮" aria-label="Permalink to &quot;一、实体操作按钮&quot;">​</a></h2><p>如果你的手机是 <strong>iPhone 15 Pro</strong> 或 <strong>iPhone 16 全系列</strong>，可以将手机的实体操作按钮设置为 Get笔记快捷指令。</p><p>设置完成后，长按手机左侧边的操作按钮（原静音按钮）即可快速打开 Get笔记。</p><h3 id="设置步骤" tabindex="-1">设置步骤 <a class="header-anchor" href="#设置步骤" aria-label="Permalink to &quot;设置步骤&quot;">​</a></h3><ol><li>打开系统「设置」，向上滑动找到「操作按钮」后点击进入</li><li>向左滑动找到「快捷指令」后，点击按钮「选取快捷指令」</li><li>在顶部搜索框输入 &quot;Get笔记&quot;，选择已添加的 Siri 快捷指令</li><li>也可以点击「打开 App…」，直接选择 Get笔记</li></ol><h2 id="二、轻点背面" tabindex="-1">二、轻点背面 <a class="header-anchor" href="#二、轻点背面" aria-label="Permalink to &quot;二、轻点背面&quot;">​</a></h2><p>轻点两下或三下 iPhone 背面即可快速执行操作。</p><h3 id="设置步骤-1" tabindex="-1">设置步骤 <a class="header-anchor" href="#设置步骤-1" aria-label="Permalink to &quot;设置步骤&quot;">​</a></h3><ol><li>在手机「设置」里，打开「辅助功能」，选择「触控」</li><li>在「触控」页面下滑至最底部，点击「轻点背面」</li><li>根据个人需求设置「轻点两下」或「轻点三下」</li><li>关联设置为 Get笔记相关的快捷指令</li></ol><h2 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>触发方式</th><th>推荐指令</th><th>场景</th></tr></thead><tbody><tr><td>操作按钮</td><td>语音速记</td><td>随时快速录音</td></tr><tr><td>轻点两下</td><td>AI 搜索</td><td>快速查找笔记</td></tr><tr><td>轻点三下</td><td>会议录音</td><td>开会时快速启动</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">小技巧</p><p>把最常用的功能设置为操作按钮，次常用的设置为轻点背面，这样可以覆盖大部分使用场景。</p></div>',14)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
